// Sanitize and structure the input parameters
const body = $input.first().json.body || $input.first().json;

const rawTranscript = body.transcript || '';
const meetingTitle = body.meeting_title || 'Client Executive Sync';
const clientName = body.client_name || 'Valued Client';
const recipientEmail = body.recipient_email || 'stakeholders@client.com';

if (!rawTranscript || rawTranscript.trim().length < 20) {
  throw new Error('Transcript is required and must contain at least 20 characters.');
}

const userPrompt = `Analyze the following meeting transcript and extract structured meeting intelligence.

Meeting Title: ${meetingTitle}
Client: ${clientName}
Target Recipient: ${recipientEmail}

RAW TRANSCRIPT:
"""
${rawTranscript}
"""

Return ONLY a valid JSON object matching the required schema with keys: meeting_title, client_name, meeting_date, attendees, executive_summary, key_discussion_points, action_items, key_decisions, risks_and_blockers, next_steps_timeline.`;

return {
  json: {
    meeting_title: meetingTitle,
    client_name: clientName,
    recipient_email: recipientEmail,
    rawTranscript: rawTranscript,
    userPrompt: userPrompt
  }
};

const item = $input.first().json;
const prevInput = $('Sanitize & Prepare Prompt').first().json;

// AI Agent outputs the response in 'output' or 'text'
let rawContent = item.output || item.text || item;

if (typeof rawContent === 'object' && rawContent.output) {
  rawContent = rawContent.output;
}

let content;
if (typeof rawContent === 'string') {
  // Strip markdown code fences if LLM wrapped it
  let cleaned = rawContent.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }

  try {
    content = JSON.parse(cleaned);
  } catch (err) {
    throw new Error('Failed to parse AI Agent JSON output: ' + err.message + ' | Raw: ' + cleaned.substring(0, 150));
  }
} else {
  content = rawContent;
}

// Ensure schema integrity
const structuredData = {
  meeting_title: content.meeting_title || prevInput.meeting_title,
  client_name: content.client_name || prevInput.client_name,
  meeting_date: content.meeting_date || new Date().toISOString().split('T')[0],
  attendees: Array.isArray(content.attendees) ? content.attendees : ['Project Stakeholders'],
  executive_summary: content.executive_summary || 'No summary generated.',
  key_discussion_points: Array.isArray(content.key_discussion_points) ? content.key_discussion_points : [],
  action_items: Array.isArray(content.action_items) ? content.action_items : [],
  key_decisions: Array.isArray(content.key_decisions) ? content.key_decisions : [],
  risks_and_blockers: Array.isArray(content.risks_and_blockers) ? content.risks_and_blockers : [],
  next_steps_timeline: content.next_steps_timeline || 'TBD'
};

const highPriorityCount = structuredData.action_items.filter(item => item.priority === 'High').length;

return {
  json: {
    structured_data: structuredData,
    recipient_email: prevInput.recipient_email,
    stats: {
      total_action_items: structuredData.action_items.length,
      high_priority_items: highPriorityCount,
      decisions_count: structuredData.key_decisions.length
    }
  }
};
